-- =====================================================================
-- BEACH BAR SEASONAL ANALYTICS - SQL PROJECT
-- =====================================================================
-- Self-contained script: schema + data + business queries, in one file.
-- 
-- Data is real (provided by an acquaintance/owner of the beach bar
-- business for academic coursework purposes, covering seasonal
-- patterns from May to September)
--
-- Business question: Does the data justify a peak-weekend sunbed price
-- increase, and what does the F&B side (products, time of day) tell us
-- that's relevant to running the business day to day?
--
-- Run this whole script in SQLite (or adapt types for MySQL/Postgres) to
-- recreate the database and see every query's result.
-- =====================================================================

-- =====================================================================
-- SECTION 1: SCHEMA

-- =====================================================================
-- ⚠️  AUDIT NOTE (F1): DROP TABLE IF EXISTS below will silently destroy
-- any existing tables with these exact names. Run this script only in a
-- NEW/dedicated database, never against a database that might already
-- contain real tables called daily_sales/products/product_sales/timezone_sales.
-- =====================================================================

PRAGMA foreign_keys = ON;  -- (F2 fix) SQLite does not enforce FKs unless explicitly turned on

DROP TABLE IF EXISTS daily_sales;
CREATE TABLE daily_sales (
    date               TEXT PRIMARY KEY,
    month              TEXT,
    month_name         TEXT,
    day_of_week        TEXT,
    is_weekend         INTEGER,   -- 1 = weekend, 0 = weekday
    weather            TEXT,
    sunbeds_available  INTEGER,
    sunbeds_booked     INTEGER,
    occupancy_rate     REAL,
    sunbed_price       REAL,
    sunbed_revenue     REAL,
    total_orders       INTEGER,
    fnb_revenue        REAL,
    total_revenue      REAL
);

DROP TABLE IF EXISTS products;
CREATE TABLE products (
    product_name        TEXT,
    category             TEXT,
    unit_price           REAL,
    popularity_weight    REAL,
    product_id            TEXT PRIMARY KEY
);

DROP TABLE IF EXISTS product_sales;
CREATE TABLE product_sales (
    date          TEXT,
    product_id    TEXT,
    product_name  TEXT,
    category      TEXT,
    unit_price    REAL,
    quantity      INTEGER,
    revenue       REAL,
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

DROP TABLE IF EXISTS timezone_sales;
CREATE TABLE timezone_sales (
    date          TEXT,
    time_zone     TEXT,   -- '09:00-12:00','12:00-15:00','15:00-18:00','18:00-21:00'
    orders        INTEGER,
    fnb_revenue   REAL
);


