-- =====================================================================
-- SECTION 3: BUSINESS QUERIES
-- =====================================================================
-- Each query starts with the business question it answers and why SQL
-- (rather than Excel/Python) is the right tool for that specific step.


-- ---------------------------------------------------------------------
-- Q1. Monthly performance: how do revenue and occupancy move across
--     the season? (grouped aggregation - SQL's natural job)
-- ---------------------------------------------------------------------
SELECT
    month_name,
    COUNT(*)                                    AS days_in_month,
    ROUND(AVG(occupancy_rate) * 100, 1)         AS avg_occupancy_pct,
    ROUND(SUM(sunbed_revenue), 0)               AS total_sunbed_revenue,
    ROUND(SUM(fnb_revenue), 0)                  AS total_fnb_revenue,
    ROUND(SUM(total_revenue), 0)                AS total_revenue,
    ROUND(SUM(total_revenue) / SUM(sunbeds_available), 2) AS revenue_per_sunbed_capacity
FROM daily_sales
GROUP BY month_name
ORDER BY MIN(date);


-- ---------------------------------------------------------------------
-- Q2. Is the bar actually AT capacity on any days, or just busier?
--     This matters directly for the pricing question: a price rise only
--     makes sense as a revenue lever where we're capacity-constrained.
-- ---------------------------------------------------------------------
SELECT
    month_name,
    CASE WHEN is_weekend = 1 THEN 'Weekend' ELSE 'Weekday' END AS day_type,
    ROUND(AVG(occupancy_rate) * 100, 1)  AS avg_occupancy_pct,
    SUM(CASE WHEN occupancy_rate >= 0.95 THEN 1 ELSE 0 END) AS days_near_full_capacity
FROM daily_sales
-- (F3 fix) grouping by the full CASE expression, not the alias, so this
-- also runs unchanged on SQL Server / Oracle (which don't allow GROUP BY alias)
GROUP BY month_name, CASE WHEN is_weekend = 1 THEN 'Weekend' ELSE 'Weekday' END
ORDER BY MIN(date), day_type;


-- ---------------------------------------------------------------------
-- Q3. Which products actually drive F&B revenue? (grouped join)
-- ---------------------------------------------------------------------
SELECT
    ps.category,
    ps.product_name,
    SUM(ps.quantity)                    AS total_units_sold,
    ROUND(SUM(ps.revenue), 0)           AS total_revenue,
    ROUND(100.0 * SUM(ps.revenue) / (SELECT SUM(revenue) FROM product_sales), 1) AS pct_of_total_fnb
FROM product_sales ps
GROUP BY ps.category, ps.product_name
ORDER BY total_revenue DESC, ps.product_name ASC;  -- (F4 fix) deterministic tie-break


-- ---------------------------------------------------------------------
-- Q4. Case study - Mojito revenue drops to zero for ~10 days in August.
--     Before concluding "unpopular, drop it from the menu", check the
--     brief's own diagnostic checklist: did overall traffic fall? did a
--     substitute product pick up the slack? (this is exactly how you'd
--     investigate a real anomaly, not just report it)
-- ---------------------------------------------------------------------
SELECT
    ps.date,
    ds.sunbeds_booked,
    ds.total_orders,
    SUM(CASE WHEN ps.product_name = 'Mojito' THEN ps.quantity ELSE 0 END) AS mojito_units,
    SUM(CASE WHEN ps.product_name = 'Aperol Spritz' THEN ps.quantity ELSE 0 END) AS aperol_units,
    SUM(CASE WHEN ps.product_name = 'Margarita' THEN ps.quantity ELSE 0 END) AS margarita_units
FROM product_sales ps
LEFT JOIN daily_sales ds ON ds.date = ps.date  -- (F8 fix) was INNER JOIN; LEFT JOIN surfaces unmatched dates instead of silently dropping them
WHERE ps.date BETWEEN '2025-08-05' AND '2025-08-24'
GROUP BY ps.date, ds.sunbeds_booked, ds.total_orders
ORDER BY ps.date;


-- ---------------------------------------------------------------------
-- Q5. Which part of the day drives F&B revenue? Client specifically
--     wants time-of-day zones checked (09-12 / 12-15 / 15-18 / 18-21).
-- ---------------------------------------------------------------------
SELECT
    time_zone,
    SUM(orders)                                 AS total_orders,
    ROUND(SUM(fnb_revenue), 0)                  AS total_fnb_revenue,
    ROUND(100.0 * SUM(fnb_revenue) / (SELECT SUM(fnb_revenue) FROM timezone_sales), 1) AS pct_of_total_fnb,
    ROUND(AVG(fnb_revenue), 1)                  AS avg_revenue_per_day
FROM timezone_sales
GROUP BY time_zone
ORDER BY
    CASE time_zone
        WHEN '09:00-12:00' THEN 1
        WHEN '12:00-15:00' THEN 2
        WHEN '15:00-18:00' THEN 3
        WHEN '18:00-21:00' THEN 4
    END;


-- ---------------------------------------------------------------------
-- Q6. Price scenario: "if we raised prices 5%, what would happen?"
--     IMPORTANT: this is a pure ARITHMETIC SCENARIO, not a forecast.
--     It assumes volume stays exactly the same after the price change.
--     Price never varied historically in this data, so real elasticity
--     is unknown - this shows a best-case ceiling, not a prediction.
-- ---------------------------------------------------------------------
SELECT 'Sunbeds' AS revenue_stream,
       ROUND(SUM(sunbed_revenue), 0)       AS actual_revenue,
       ROUND(SUM(sunbed_revenue) * 1.05, 0) AS scenario_revenue_plus_5pct,
       ROUND(SUM(sunbed_revenue) * 0.05, 0) AS scenario_uplift_if_volume_unchanged
FROM daily_sales
UNION ALL
SELECT 'F&B (all products)',
       ROUND(SUM(revenue), 0),
       ROUND(SUM(revenue) * 1.05, 0),
       ROUND(SUM(revenue) * 0.05, 0)
FROM product_sales;